const data = $input.first().json;
const anomalies = data.anomalies || [];

// Group by severity
const critical = anomalies.filter(a => a.severity === 'critical');
const high = anomalies.filter(a => a.severity === 'high');
const medium = anomalies.filter(a => a.severity === 'medium');

const today = new Date().toLocaleDateString('en-IN', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    body {
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      margin: 0;
      padding: 20px;
      background: #f5f7fa;
    }
    .container {
      max-width: 700px;
      margin: 0 auto;
      background: white;
      border-radius: 16px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.1);
      overflow: hidden;
    }
    .header {
      background: linear-gradient(135deg, #dc2626 0%, #991b1b 100%);
      color: white;
      padding: 30px;
      text-align: center;
    }
    .header h1 {
      margin: 0 0 10px;
      font-size: 24px;
    }
    .content {
      padding: 30px;
    }
    .summary-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 15px;
      margin-bottom: 30px;
    }
    .summary-card {
      padding: 20px;
      border-radius: 10px;
      text-align: center;
    }
    .summary-card.critical {
      background: #fee2e2;
      border: 2px solid #dc2626;
    }
    .summary-card.high {
      background: #fef3c7;
      border: 2px solid #d97706;
    }
    .summary-card.medium {
      background: #dbeafe;
      border: 2px solid #2563eb;
    }
    .summary-value {
      font-size: 32px;
      font-weight: bold;
    }
    .summary-card.critical .summary-value { color: #dc2626; }
    .summary-card.high .summary-value { color: #d97706; }
    .summary-card.medium .summary-value { color: #2563eb; }
    .anomaly-item {
      background: #f8f9fa;
      border-radius: 10px;
      padding: 20px;
      margin: 15px 0;
      border-left: 4px solid #dc2626;
    }
    .anomaly-item.high {
      border-color: #d97706;
    }
    .anomaly-item.medium {
      border-color: #2563eb;
    }
    .anomaly-title {
      font-weight: 600;
      font-size: 16px;
      margin-bottom: 8px;
    }
    .anomaly-details {
      color: #666;
      font-size: 14px;
    }
    .badge {
      display: inline-block;
      padding: 4px 10px;
      border-radius: 20px;
      font-size: 12px;
      font-weight: 600;
      margin-left: 10px;
    }
    .badge.critical { background: #dc2626; color: white; }
    .badge.high { background: #d97706; color: white; }
    .badge.medium { background: #2563eb; color: white; }
    .footer {
      background: #f8f9fa;
      padding: 20px;
      text-align: center;
      color: #666;
      font-size: 12px;
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>🚨 AI Anomaly Detection Alert</h1>
      <p>${today}</p>
    </div>

    <div class="content">
      <div class="summary-grid">
        <div class="summary-card critical">
          <div class="summary-value">${critical.length}</div>
          <div>Critical</div>
        </div>
        <div class="summary-card high">
          <div class="summary-value">${high.length}</div>
          <div>High</div>
        </div>
        <div class="summary-card medium">
          <div class="summary-value">${medium.length}</div>
          <div>Medium</div>
        </div>
      </div>

      <h3>Detected Anomalies</h3>
      ${anomalies.slice(0, 10).map(a => `
        <div class="anomaly-item ${a.severity}">
          <div class="anomaly-title">
            ${a.anomaly_type === 'sudden_drop' ? '📉' : '⚠️'} ${a.description || a.anomaly_type}
            <span class="badge ${a.severity}">${a.severity?.toUpperCase()}</span>
          </div>
          <div class="anomaly-details">
            ${a.student_name ? `Student: <strong>${a.student_name}</strong> | ` : ''}
            ${a.class_name ? `Class: <strong>${a.class_name}</strong> | ` : ''}
            ${a.expected_rate ? `Expected: ${a.expected_rate.toFixed(1)}% | Actual: ${a.actual_rate?.toFixed(1)}%` : ''}
          </div>
        </div>
      `).join('')}
      ${anomalies.length > 10 ? `<p style="color: #666;">... and ${anomalies.length - 10} more anomalies</p>` : ''}
    </div>

    <div class="footer">
      <p>AI-Powered Anomaly Detection | SmartAttend Hub</p>
      <p>Please review these anomalies in the dashboard for detailed analysis.</p>
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    html,
    subject: `🚨 AI Alert: ${anomalies.length} Anomalies Detected - ${today}`,
    anomaly_count: anomalies.length,
    critical_count: critical.length,
    anomalies
  }
}];
